import { useState } from 'react';
import Display from './components/Display';
import Buttons from './components/Buttons';

export default function App(){
  const [input,setInput]=useState('');

  const handleClick = (val)=>{
    if(val==='C') setInput('');
    else if(val==='='){
      try{ setInput(eval(input).toString()); }
      catch{ setInput('Error'); }
    }else{
      setInput(input + val);
    }
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-900">
      <div className="bg-gray-800 p-4 rounded-2xl shadow-lg w-80">
        <Display value={input} />
        <Buttons onButtonClick={handleClick} />
      </div>
    </div>
  )
}

// src/components/Buttons.jsx
export default function Buttons({onButtonClick}){
  const btns=['7','8','9','/','4','5','6','*','1','2','3','-','0','.','=','+','C'];
  return (
    <div className="grid grid-cols-4 gap-2">
      {btns.map(b=>(
        <button key={b} onClick={()=>onButtonClick(b)} className="bg-gray-700 text-white p-4 rounded-lg hover:bg-gray-600">
          {b}
        </button>
      ))}
    </div>
  )
}

// src/utils/calculate.js
export function calculate(expr){
  try{
    return eval(expr).toString();
  }catch{
    return 'Error';
  }
}

// src/App.jsx
import { calculate } from './utils/calculate';

const handleClick=(val)=>{
  if(val==='C') setInput('');
  else if(val==='=') setInput(calculate(input));
  else setInput(input+val);
}

// optional keyboard listener
useEffect(()=>{
  const handleKey=(e)=>{
    const keys='0123456789+-*/.=C';
    if(keys.includes(e.key)) handleClick(e.key);
  }
  window.addEventListener('keydown',handleKey);
  return()=>window.removeEventListener('keydown',handleKey);
},[input]);
